		BindingSetOrigin inputOrigin = BindingSetOrigin.of(requestInput);
		QueryBindingSet mappedInput = new QueryBindingSet(requestInput);
		BindingSetOrigin.set(mappedInput, inputOrigin.producing(Set.of("local")));
		QueryBindingSet graphSource = new QueryBindingSet();
		Value shadowGraph = VALUE_FACTORY.createIRI("urn:test:present-null-shadow-graph");
		GraphFrameBindings.supply(graphSource, "value", shadowGraph);
		GraphFrameBindings.supply(graphSource, "privateGraph", privateGraph);
		var graphInput = GraphFrameBindings.preserve(graphSource, mappedInput);
		GraphFrameBindings.supply(graphInput, "privateGraph", privateGraph);
		BindingSet input = graphInput;
		assertSame(shadowGraph, GraphFrameBindings.from(input).retainedParametersForTransport().get("value"));
		assertFalse(GraphFrameBindings.isSupplied(input, "value"), "the present-null mapping is not the graph value");
		assertTrue(input.hasBinding("value"), "present-null remains in the input mapping domain");
		assertThat(input.getValue("value")).isNull();
		assertTrue(BindingSetOrigin.of(input).isRequest("value"));
		assertTrue(BindingSetOrigin.of(input).isRequest("payload"));
		assertTrue(BindingSetOrigin.of(input).isLocal("local"));

		TrackingTupleFunction function = function(List.of(List.of(resultValue)));
		List<BindingSet> actual = drain(open(entryPoint, function, List.of(new Var("value")), input));

