		assertSame(resultValue, result.getValue("value"));
		assertSame(local, result.getValue("local"));
		assertSame(privateGraph, result.getValue("privateGraph"));
		BindingSet reentered = BindingSetOrigin.optimizationInput(result);
		BindingSetOrigin resultOrigin = BindingSetOrigin.of(reentered);
		assertTrue(reentered.hasBinding("value"));
		assertSame(resultValue, reentered.getValue("value"));
		assertTrue(resultOrigin.isLocal("value"));
		assertFalse(resultOrigin.isRequest("value"));
		assertThat(resultOrigin.parameterValue("value")).isNull();
		assertFalse(reentered.hasBinding("payload"));
		assertSame(payload, resultOrigin.parameterValue("payload"));
		assertFalse(resultOrigin.isRequest("local"));
		assertTrue(resultOrigin.isLocal("local"));
		BindingSet materialized = BindingSetOrigin.materializeParameters(reentered,
				List.of(Var.of("payload", payload, false, false)), new QueryEvaluationContext.Minimal(null));
		assertSame(resultValue, materialized.getValue("value"));
		assertSame(payload, materialized.getValue("payload"));
