	@ParameterizedTest(name = "{0}")
	@EnumSource(EntryPoint.class)
	void newlyWrittenOutputMasksAHiddenRequestBeforeOptimizationReentry(EntryPoint entryPoint) {
		Value staleOutputParameter = VALUE_FACTORY.createLiteral("stale-output-parameter", "en");
		Value hiddenPayload = VALUE_FACTORY.createLiteral("hidden-payload", "EN");
		Value producedValue = VALUE_FACTORY.createLiteral("tuple-output", "en");
		Value privateGraph = VALUE_FACTORY.createIRI("urn:test:tuple-function-reentry-graph");
		QueryBindingSet rawRequest = new QueryBindingSet();
		rawRequest.setBinding("value", staleOutputParameter);
		rawRequest.setBinding("payload", hiddenPayload);
		BindingSet input = GraphFrameBindings.supply(
				new QueryBindingSet(BindingSetOrigin.optimizationInput(rawRequest)), "privateGraph", privateGraph);
		assertFalse(input.hasBinding("value"));
		assertFalse(input.hasBinding("payload"));
		assertSame(staleOutputParameter, BindingSetOrigin.of(input).parameterValue("value"));
		assertSame(hiddenPayload, BindingSetOrigin.of(input).parameterValue("payload"));

		TrackingTupleFunction function = function(List.of(List.of(producedValue)));
		List<BindingSet> actual = drain(open(entryPoint, function, List.of(new Var("value")), input));
		assertThat(bag(actual)).containsExactly(Map.of("value", producedValue, "privateGraph", privateGraph));

		// Re-enter through the downstream parameter materializer, which copies tracked request and GRAPH metadata.
		BindingSet materialized = BindingSetOrigin.materializeParameters(actual.get(0),
				List.of(Var.of("payload", hiddenPayload, false, false)), new QueryEvaluationContext.Minimal(null));
		assertTrue(materialized.hasBinding("value"), "a produced value must remain in the solution mapping");
		assertSame(producedValue, materialized.getValue("value"));
		assertSame(hiddenPayload, materialized.getValue("payload"));
		BindingSetOrigin materializedOrigin = BindingSetOrigin.of(materialized);
		assertTrue(materializedOrigin.isLocal("value"));
		assertFalse(materializedOrigin.isRequest("value"));
		assertThat(materializedOrigin.parameterValue("value")).isNull();
		assertSame(staleOutputParameter, materializedOrigin.retainedParametersForTransport().get("value"),
				"the older hidden payload remains retained but masked by the local write");
		assertTrue(materializedOrigin.isRequest("payload"));
		assertSame(privateGraph,
				GraphFrameBindings.from(materialized).retainedParametersForTransport().get("privateGraph"));
		assertTrue(GraphFrameBindings.isSupplied(materialized, "privateGraph"));

		// The real optimization-input adapter must also keep the local result in the mapping instead of promoting it
		// back into the stale request payload. Its contract deliberately does not transport GRAPH metadata.
		BindingSet reentered = BindingSetOrigin.optimizationInput(actual.get(0));
		assertTrue(reentered.hasBinding("value"), "a produced value must remain in the solution mapping");
		assertSame(producedValue, reentered.getValue("value"));
		BindingSetOrigin reenteredOrigin = BindingSetOrigin.of(reentered);
		assertTrue(reenteredOrigin.isLocal("value"));
		assertFalse(reenteredOrigin.isRequest("value"));
		assertThat(reenteredOrigin.parameterValue("value")).isNull();
		assertSame(staleOutputParameter, reenteredOrigin.retainedParametersForTransport().get("value"),
				"the older hidden payload remains retained but masked by the local write");
		assertFalse(reentered.hasBinding("payload"));
		assertTrue(reenteredOrigin.isRequest("payload"));
		assertSame(hiddenPayload, reenteredOrigin.parameterValue("payload"));
		assertFalse(GraphFrameBindings.isSupplied(reentered, "privateGraph"));
		assertThat(function.closes).hasValue(1);
	}

