	void preboundNamesFilterRowsAndPreserveRequestLocalAndGraphAuthority(EntryPoint entryPoint) {
		Value request = VALUE_FACTORY.createLiteral("requested", "en");
		Value requestEquivalent = VALUE_FACTORY.createLiteral("requested", "EN");
		Value local = VALUE_FACTORY.createLiteral("local");
		Value localEquivalent = VALUE_FACTORY.createLiteral("local");
		Value privateGraph = VALUE_FACTORY.createIRI("urn:test:private-graph");
		Value independent = VALUE_FACTORY.createLiteral("independent");
		Value mismatch = VALUE_FACTORY.createLiteral("mismatch", "en");
		Value localMismatch = VALUE_FACTORY.createLiteral("different-local");
		MapBindingSet rawInput = new MapBindingSet();
		rawInput.addBinding("request", request);
		rawInput.addBinding("local", local);
		BindingSet requestInput = BindingSetOrigin.requestInput(rawInput);
		assertThat(requestEquivalent).isEqualTo(request).isNotSameAs(request);
		assertThat(localEquivalent).isEqualTo(local).isNotSameAs(local);
		BindingSetOrigin requestOrigin = BindingSetOrigin.of(requestInput);
		QueryBindingSet mappedInput = new QueryBindingSet(requestInput);
		BindingSetOrigin.set(mappedInput, requestOrigin.producing(Set.of("local")));
		BindingSet input = GraphFrameBindings.supply(mappedInput, "privateGraph", privateGraph);

		TrackingTupleFunction function = function(
				List.of(List.of(requestEquivalent, localEquivalent, independent),
						List.of(mismatch, localEquivalent, independent),
						List.of(requestEquivalent, localMismatch, independent)));
		List<BindingSet> actual = drain(open(entryPoint, function,
				List.of(new Var("request"), new Var("local"), new Var("independent")), input));

		assertThat(bag(actual)).containsExactly(Map.of("request", request, "local", local,
				"privateGraph", privateGraph, "independent", independent));
		BindingSet result = actual.get(0);
		assertSame(request, result.getValue("request"));
		assertSame(local, result.getValue("local"));
		assertSame(privateGraph, result.getValue("privateGraph"));
		assertSame(independent, result.getValue("independent"));
		BindingSetOrigin resultOrigin = BindingSetOrigin.of(result);
		if (entryPoint == EntryPoint.DEFAULT_PRECOMPILE) {
			// The current prepared tuple-function producer marks every declared result name as produced.
			assertTrue(resultOrigin.isLocal("request"));
			assertFalse(resultOrigin.isRequest("request"));
		} else {
			assertTrue(resultOrigin.isRequest("request"));
			assertFalse(resultOrigin.isLocal("request"));
		}
		assertTrue(resultOrigin.isLocal("local"));
		assertFalse(resultOrigin.isRequest("local"));
		// requestInput marks actual mapped names; unlike optimizationInput it retains no hidden parameter values.
		assertThat(resultOrigin.parameterValue("request")).isNull();
		assertThat(resultOrigin.parameterValue("local")).isNull();
		assertTrue(GraphFrameBindings.isSupplied(result, "privateGraph"));
		assertSame(privateGraph, GraphFrameBindings.from(result).retainedParametersForTransport()
				.get("privateGraph"));
		assertThat(function.closes).hasValue(1);
	}

