	@ParameterizedTest(name = "{0}")
	@EnumSource(EntryPoint.class)
	void earlyCloseRetiresTheProducerOnce(EntryPoint entryPoint) {
		TrackingTupleFunction function = function(List.of(
				List.of(VALUE_FACTORY.createLiteral("first")),
				List.of(VALUE_FACTORY.createLiteral("second"))));
		CloseableIteration<BindingSet> actual = open(entryPoint, function, List.of(new Var("value")),
				EmptyBindingSet.getInstance());

		assertTrue(actual.hasNext());
		assertThat(actual.next().getValue("value")).isEqualTo(VALUE_FACTORY.createLiteral("first"));
		actual.close();
		assertFalse(actual.hasNext());
		assertThat(function.nextCalls).hasValue(1);
		assertThat(function.closes).hasValue(1);
	}

